// function gradePoints(grade) mein grade string do
// "A+": 4.0, "A": 3.7, "B+": 3.3, "B": 3.0, "C": 2.0, "F": 0.0
// Invalid grade: -1

solution:
function gradePoints(grade) {
  switch (grade) {
    case "A+": return 4.0
    case "A": return 3.7
    case "B+": return 3.3
    case "B": return 3.0
    case "C": return 2.0
    case "F": return 0.0
    default: return -1
  }
}
